/**
 * Generates lib/heuristic-literals.ts: the prefilter literals of each built-in detect pattern, in DETECT_PATTERNS order,
 * so pages don't parse the pattern sources at load time. Run after changing DETECT_PATTERNS and commit the result; a
 * unit test fails while it is stale. See docs/heuristic-prefilter.md.
 */
import fs from 'fs';
import path from 'path';
import { detectLiteralTable } from './required-literals';

const OUT = path.join(__dirname, '../lib/heuristic-literals.ts');

const table = detectLiteralTable();
fs.writeFileSync(
    OUT,
    [
        '// Generated by `npm run build-heuristic-literals` from DETECT_PATTERNS. Do not edit.',
        '// Entry i holds the literals DETECT_PATTERNS[i] needs to match (see docs/heuristic-prefilter.md).',
        'export const DETECT_PATTERN_LITERALS: string[][] = [',
        ...table.map((literals) => `    ${JSON.stringify(literals)},`),
        '];',
        '',
    ].join('\n'),
);
console.log(`Wrote ${path.relative(process.cwd(), OUT)} (${table.length} patterns)`);
